import {uid,invoiceStatus,saveClient} from './domain.js';
import {deliveryStatus} from './workspace-domain.js';
export const crmSchemas={
 clients:{title:'Clients',singular:'client',action:'new-client',columns:[['name','Client','clients'],['contact','Contact','clients'],['email','Email','mail'],['tag','Service','tag'],['projects','Projects','projects']],filters:[['status','Status'],['tag','Service']]},
 projects:{title:'Projects',singular:'project',action:'new-project',columns:[['name','Project','projects'],['client','Client','clients'],['status','Status','status'],['budget','Fee','money'],['progress','Phases','check'],['due','Target date','calendar']],filters:[['status','Status'],['client','Client']]},
 documents:{title:'Documents',singular:'document',action:'new-document',columns:[['name','Document','documents'],['client','Client','clients'],['kind','Type','tag'],['status','Status','status'],['response','Response','signature'],['updated','Updated','calendar']],filters:[['status','Status'],['kind','Type'],['client','Client']]},
 invoices:{title:'Invoices',singular:'invoice',action:null,columns:[['name','Invoice','invoices'],['client','Client','clients'],['project','Project','projects'],['status','Status','status'],['amount','Amount','money'],['balance','Balance','money'],['due','Due date','calendar']],filters:[['status','Status'],['client','Client']]},
 forms:{title:'Forms',singular:'form',action:'new-form',columns:[['name','Form','forms'],['status','Status','status'],['submissions','Submissions','forms'],['service','Service','tag'],['tag','Inquiry tag','tag']],filters:[['status','Status'],['service','Service']]},
 submissions:{title:'Submissions',singular:'submission',action:null,columns:[['name','Project request','forms'],['client','Client','clients'],['form','Form','forms'],['received','Received','calendar']],filters:[['form','Form'],['client','Client']]}
};
const kinds={proposal:'Proposal',contract:'Contract',agreement:'Proposal + contract',document:'Document'},responses={acceptance:'Acceptance',signature:'Signature',none:'No response'};
export function initCRM(s){s.crm??={views:{},active:{},notes:[]};s.crm.views??={};s.crm.active??={};s.crm.notes??=[];return s.crm;}
export function defaultConfig(entity){return {filters:{},archive:false,sort:'',direction:'asc',columns:crmSchemas[entity].columns.map(c=>c[0]),density:'compact',layout:'table'};}
export function builtInViews(entity){const base=defaultConfig(entity);const out=[{id:'all',name:`All ${crmSchemas[entity].title.toLowerCase()}`,config:base,builtIn:true}];if(entity==='projects')out.push({id:'board',name:'By stage',builtIn:true,config:{...base,layout:'board'}});if(entity==='documents')out.push({id:'drafts',name:'Drafts',builtIn:true,config:{...base,filters:{status:'draft'}}});if(entity==='invoices')out.push({id:'unpaid',name:'Unpaid',builtIn:true,config:{...base,filters:{status:'unpaid'}}});if(!['invoices','submissions'].includes(entity))out.push({id:'archived',name:'Archived',builtIn:true,config:{...base,archive:true}});return out;}
export function viewsFor(s,entity){return [...builtInViews(entity),...(initCRM(s).views[entity]||[])];}
export function validateView(entity,config){const schema=crmSchemas[entity];if(!schema)throw Error('Unknown record type.');const columns=config.columns?.filter(c=>schema.columns.some(x=>x[0]===c));if(!columns?.includes('name'))throw Error('The name column must remain visible.');const allowed=schema.filters.map(x=>x[0]);return {filters:Object.fromEntries(Object.entries(config.filters||{}).filter(([k,v])=>allowed.includes(k)&&typeof v==='string'&&v)),archive:!!config.archive,sort:schema.columns.some(c=>c[0]===config.sort)?config.sort:'',direction:config.direction==='desc'?'desc':'asc',columns:[...new Set(columns)],density:config.density==='comfortable'?'comfortable':'compact',layout:entity==='projects'&&config.layout==='board'?'board':'table'};}
export function saveCRMView(s,entity,name,config,id){name=String(name||'').trim();if(!name||name.length>60)throw Error('Use a view name of 1–60 characters.');const valid=validateView(entity,config),crm=initCRM(s),all=viewsFor(s,entity);if(all.some(v=>v.id!==id&&v.name.toLowerCase()===name.toLowerCase()))throw Error('A view with this name already exists.');const target=id?(crm.views[entity]||[]).find(v=>v.id===id):null;if(id&&!target)throw Error('Create a new view to customize a default view.');const view={id:target?.id||uid(),name,config:valid};if(target)Object.assign(target,view);else (crm.views[entity]??=[]).push(view);crm.active[entity]=view.id;return view;}
export function deleteCRMView(s,entity,id){const crm=initCRM(s);if(!(crm.views[entity]||[]).some(v=>v.id===id))throw Error('Default views cannot be deleted.');crm.views[entity]=crm.views[entity].filter(v=>v.id!==id);if(crm.active[entity]===id)crm.active[entity]='all';}
export function crmRecords(s,entity){const client=id=>s.clients.find(c=>c.id===id),project=id=>s.projects.find(p=>p.id===id);switch(entity){
 case 'clients':return s.clients.map(c=>({id:c.id,name:c.name,contact:c.contact,email:c.email,tag:c.tag,projects:s.projects.filter(p=>p.clientId===c.id).length,status:c.archived?'archived':'active',archived:!!c.archived,raw:c}));
 case 'projects':return s.projects.map(p=>({id:p.id,name:p.name,client:client(p.clientId)?.name||'',clientId:p.clientId,status:deliveryStatus(p),budget:p.needsPricing?null:p.budget,progress:p.phases.filter(f=>f.done).length/p.phases.length,due:p.due||null,archived:!!p.archived,raw:p}));
 case 'documents':return s.documents.map(d=>({id:d.id,name:d.title,client:client(d.clientId)?.name||'',clientId:d.clientId,kind:kinds[d.kind],status:d.status,response:responses[d.responseMode],updated:d.updatedAt,archived:!!d.archived,raw:d}));
 case 'invoices':return s.invoices.map(i=>({id:i.id,name:i.number,client:i.clientName||client(project(i.projectId)?.clientId)?.name||'',clientId:project(i.projectId)?.clientId,project:i.projectName||project(i.projectId)?.name,status:invoiceStatus(i),amount:i.amount,balance:i.amount-i.paid,due:i.due||null,archived:false,raw:i}));
 case 'forms':return s.forms.map(f=>({id:f.id,name:f.name,status:f.status,submissions:s.submissions.filter(x=>x.formId===f.id).length,service:f.service,tag:f.tag,archived:f.status==='archived',raw:f}));
 case 'submissions':return s.submissions.map(x=>({id:x.id,name:project(x.projectId)?.name||'Project request',client:x.clientName||client(x.clientId)?.name||'',clientId:x.clientId,form:x.formTitle,received:x.createdAt,archived:false,raw:x}));
 default:return [];
}}
export function queryCRM(records,config,search=''){const q=search.trim().toLowerCase();const list=records.filter(r=>r.archived===!!config.archive&&Object.entries(config.filters||{}).every(([key,value])=>!value||(key==='status'&&value==='unpaid'?['overdue','outstanding'].includes(r.status):String(r[key]??'')===value))&&(!q||Object.entries(r).some(([k,v])=>k!=='raw'&&typeof v==='string'&&v.toLowerCase().includes(q))));if(!config.sort)return list;const key=config.sort,dir=config.direction==='desc'?-1:1;return list.sort((a,b)=>{const av=a[key],bv=b[key];if(av==null||av==='')return bv==null||bv===''?0:1;if(bv==null||bv==='')return -1;return (typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),undefined,{numeric:true,sensitivity:'base'}))*dir;});}
export function addClientNote(s,clientId,body){if(!s.clients.some(c=>c.id===clientId))throw Error('Client not found.');body=String(body||'').trim();if(!body||body.length>5000)throw Error('Write a note of 1–5,000 characters.');const note={id:uid(),clientId,body,author:s.settings.name,createdAt:new Date().toISOString()};initCRM(s).notes.unshift(note);return note;}
export function editClientField(s,id,key,value){if(!['contact','email','tag'].includes(key))throw Error('This field cannot be edited inline.');const c=s.clients.find(c=>c.id===id);if(!c)throw Error('Client not found.');return saveClient(s,{...c,[key]:String(value).trim()},id);}
